int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t max_pairs) {
    size_t pair_count = 0;
    while (pair_count < max_pairs) {
        const char *eq = strchr(in, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - in);
        keys_out[pair_count] = malloc(klen + 1);
        strncpy(keys_out[pair_count], in, klen);
        keys_out[pair_count][klen] = '\0';

        const char *val_start = eq + 1;
        if (*val_start == '"') {
            const char *quote = strchr(val_start + 1, '"');
            if (!quote) break;
            size_t vlen = (size_t)(quote - val_start) - 1;
            vals_out[pair_count] = malloc(vlen + 1);
            strncpy(vals_out[pair_count], val_start + 1, vlen);
            vals_out[pair_count][vlen] = '\0';
            in = quote + 1;
        } else {
            const char *space = strchr(val_start, ' ');
            size_t vlen = space ? (size_t)(space - val_start) : strlen(val_start);
            vals_out[pair_count] = malloc(vlen + 1);
            strncpy(vals_out[pair_count], val_start, vlen);
            vals_out[pair_count][vlen] = '\0';
            in = space ? space + 1 : in + vlen;
        }

        pair_count++;
        if (*in == ' ') in++;
    }

    return pair_count;
}

